class ManualBlock(val kind: ManualKind, val text: String)

class ManualSection(
    val title: String,
    val summary: String,
    val blocks: List<ManualBlock>,
    /** Pages of this one's own: a machine is more than a line. */
    val children: List<ManualSection> = emptyList(),
)

object Manual {
    val sections: List<ManualSection> = listOf(
        ManualSection("A first song", "Tracks, scenes, clips, and a first sound.", listOf(
            ManualBlock(ManualKind.Para, "Acidulous is sixteen racks. A rack holds one machine - a synthesizer, a drum machine, a sampler - and that machine is also a track in the song. There is no separate list of instruments and list of parts: the track *is* the instrument."),
            ManualBlock(ManualKind.Heading, "What you are looking at"),
            ManualBlock(ManualKind.Para, "The first screen is the song grid. Track names run down the left, one row each. Scenes run across the top, one column each. Where a row and a column meet there is a clip: the notes that track plays during that scene."),
            ManualBlock(ManualKind.Para, "The bar at the foot of the screen is the same on every screen. Its right-hand end is always the same five controls in the same order - undo, redo, mixer, record and play - so the one you want is where you left it."),
            ManualBlock(ManualKind.Heading, "Making a sound"),
            ManualBlock(ManualKind.Step, "Tap **+ track** and pick a machine. A new song starts with one already."),
            ManualBlock(ManualKind.Step, "Tap the empty clip where your new track meets the first scene. That opens the editor."),
            ManualBlock(ManualKind.Step, "Play the keyboard at the bottom. That is the machine as it stands; tap **patch** at the top of the panel to try the ones it ships with."),
            ManualBlock(ManualKind.Step, "Draw notes in the grid above, or press record and play them in."),
            ManualBlock(ManualKind.Step, "Tap the back arrow to return to the song, and press play."),
            ManualBlock(ManualKind.Heading, "Scenes are sections"),
            ManualBlock(ManualKind.Para, "A scene is a part of the song - an intro, a verse. Every track's clip in that scene plays together, and the scene repeats for as many times as its header says before the song moves to the next one."),
            ManualBlock(ManualKind.Para, "Clips in one scene need not be the same length. A one-bar drum clip under a four-bar chord clip simply repeats four times, which is how most parts are written anyway."),
            ManualBlock(ManualKind.Heading, "Saving"),
            ManualBlock(ManualKind.Para, "The song you are working on is saved continuously and comes back when you next open the app, so nothing is lost by closing it. **save** in the header writes it under its own name; **file** offers a new song, a copy under another name, and the songs you already have."),
        )),
        ManualSection("The song grid", "The arranger, the launcher, and freezing.", listOf(
            ManualBlock(ManualKind.Para, "The grid does two jobs, and the square in its top left corner says which one it is doing."),
            ManualBlock(ManualKind.Heading, "As an arranger"),
            ManualBlock(ManualKind.Para, "This is the default. The song plays scene by scene, left to right: every track plays its clip for that scene, the scene repeats as many times as its header says, and then the next one starts. Press play and it plays the song."),
            ManualBlock(ManualKind.Bullet, "Tap a scene's header to hear that scene on its own."),
            ManualBlock(ManualKind.Bullet, "Hold a scene's header for its menu: settings, insert, duplicate, delete, and move it left or right."),
            ManualBlock(ManualKind.Bullet, "The loop pill at the left of the bottom bar loops the whole song or the scene that is playing."),
            ManualBlock(ManualKind.Heading, "As a launcher"),
            ManualBlock(ManualKind.Para, "Tap the corner square and the same grid becomes a launcher: every track picks its own clip, from any scene, and they need not be from the same one."),
            ManualBlock(ManualKind.Bullet, "Tap a clip to launch it. It starts on the next line rather than immediately, so it arrives in time with what is already playing."),
            ManualBlock(ManualKind.Bullet, "The **q:** pill sets what it waits for. **end** is the musical answer: the clip you are replacing finishes the cycle it is in. Anything else is a plain grid of bars."),
            ManualBlock(ManualKind.Bullet, "Tap a scene's header to launch that whole column at once."),
            ManualBlock(ManualKind.Bullet, "Tap a playing clip to stop it at the end of its cycle; tap the stop control twice to cut everything."),
            ManualBlock(ManualKind.Para, "Every track keeps its own count in this mode, which is the whole point, and the readout above the bottom bar is the only place you can read that as a number."),
            ManualBlock(ManualKind.Heading, "Zooming the grid"),
            ManualBlock(ManualKind.Para, "Two fingers move the grid and change how much of it you can see - drag to move around it, pinch to make the cells larger or smaller. One finger still launches or opens a clip, so nothing is in the way of playing."),
            ManualBlock(ManualKind.Heading, "Clip settings"),
            ManualBlock(ManualKind.Para, "Hold a clip for its settings: how many bars it is, whether it is muted, and the grid it snaps to."),
            ManualBlock(ManualKind.Heading, "What a cell tells you"),
            ManualBlock(ManualKind.Para, "The number of bars is in the corner, with **1** for a one-shot and **M** for a muted clip. A cell on an audio track also shows its waveform and how many of its four lanes hold a recording - and says so **in amber** when one of them was recorded at a tempo this scene does not play at, since audio does not stretch."),
            ManualBlock(ManualKind.Heading, "Freezing"),
            ManualBlock(ManualKind.Para, "Freezing renders a clip to audio and plays that instead of the machine, which gives the processor back to everything else. Freeze one clip, a whole scene or a whole track from the menus."),
            ManualBlock(ManualKind.Para, "A freeze is tied to the tempo it was made at. Change the tempo and the frozen clips say so, and can be thawed or re-frozen."),
        )),
        ManualSection("The editor", "Drawing notes, and what one note decides.", listOf(
            ManualBlock(ManualKind.Para, "Opening a clip gives you the grid at the top, the machine's own controls in the middle, and the instrument at the bottom."),
            ManualBlock(ManualKind.Heading, "The grid"),
            ManualBlock(ManualKind.Para, "For a melodic machine it is a piano roll: pitch up the side, time across."),
            ManualBlock(ManualKind.Bullet, "Tap an empty square to put a note there; tap a note to take it away."),
            ManualBlock(ManualKind.Bullet, "Drag a note to move it, or drag its right-hand edge to make it longer."),
            ManualBlock(ManualKind.Bullet, "**Two fingers move the view**: drag to scroll through pitch and time, pinch to zoom. One finger always draws, which is what keeps the two apart."),
            ManualBlock(ManualKind.Bullet, "The **scl** corner cycles how the scale is shown: every note, the scale's notes lit, or only the scale's notes."),
            ManualBlock(ManualKind.Para, "For a drum machine it is a grid of steps instead, one row per voice, and a tap puts a hit in."),
            ManualBlock(ManualKind.Heading, "Playing it in"),
            ManualBlock(ManualKind.Para, "Press record and play. What you play is written into the clip, quantised to the clip's grid. The count-in, if you have set one, is in the settings."),
            ManualBlock(ManualKind.Para, "The keyboard reads **where** you hit a key: low on the key is soft, high is hard. The pill in the bottom bar switches that off, so every note comes out at full strength - which is what you want when you are tapping a part in rather than playing it. The drum pads work the same way and have their own setting."),
            ManualBlock(ManualKind.Para, "Drag the performance row - the strip of controls just above the keys - up or down to make the instrument taller or shorter."),
            ManualBlock(ManualKind.Heading, "What a note can decide"),
            ManualBlock(ManualKind.Para, "Below the grid is a lane, folded away until you want it. Open it and pick what it is showing; then drag inside it to set that property on each note."),
            ManualBlock(ManualKind.Bullet, "**note volume** - how hard that note is played."),
            ManualBlock(ManualKind.Bullet, "**probability** - how often it plays at all. A note at 50 plays half the time."),
            ManualBlock(ManualKind.Bullet, "**trig condition** - when it is allowed to play. `1:4` plays on the first of every four passes; `pre` plays only if the last conditional note played, `!pr` only if it did not; `fil` plays only while fill is held, `!fi` only while it is not."),
            ManualBlock(ManualKind.Bullet, "**ratchet** - how many times it retriggers within its own step."),
            ManualBlock(ManualKind.Bullet, "**micro timing** - how far off the grid it sits, up to half a sixteenth either way."),
            ManualBlock(ManualKind.Para, "The same seed drives every one of these, so a clip that varies still plays the same bar twice when you want it to."),
            ManualBlock(ManualKind.Heading, "Automation"),
            ManualBlock(ManualKind.Para, "The strip under the note lane records and draws a parameter over time. Move any knob while recording and the move is written there; afterwards, pick the parameter and draw it by hand."),
            ManualBlock(ManualKind.Heading, "Folding"),
            ManualBlock(ManualKind.Para, "The lanes, the machine panel and the instrument each fold away with the small chevron at their edge, and the grid takes the height. On a phone that is the difference between four rows of pitch and fourteen."),
        )),
        ManualSection("The machines", "Nineteen instruments, a four-track for your recordings, and what each is for.", listOf(
            ManualBlock(ManualKind.Para, "A track's machine is what it plays. Every track has one, chosen when you make the track and changed at any time from the name at the top of the editor. **Each machine has a page of its own below** with what it does and how to get the best from it; this page is for finding the one you want."),
            ManualBlock(ManualKind.Heading, "Bass and lead"),
            ManualBlock(ManualKind.Bullet, "**Reflux** - acid bass. One oscillator, one filter that screams, accent on velocity and slide on legato, so a line is played rather than programmed."),
            ManualBlock(ManualKind.Bullet, "**Trinity** - the general-purpose poly. Three wavetable oscillators, density and drift, two filters and a mod matrix."),
            ManualBlock(ManualKind.Bullet, "**Ratio** - six-operator FM, with the algorithm itself on a knob so it can morph between two of them."),
            ManualBlock(ManualKind.Heading, "Keys and air"),
            ManualBlock(ManualKind.Bullet, "**Cumulus** - pads by spectrum. You describe the sound's shape and the machine builds it, which is why it sounds like nothing else here."),
            ManualBlock(ManualKind.Bullet, "**Manual** - a tonewheel organ: two manuals and pedals over one shared generator, four models, and a cabinet that spins."),
            ManualBlock(ManualKind.Bullet, "**Formulate** - the 8-bit machine: chip oscillators, tracker tables, and a waveform you can type in as an equation."),
            ManualBlock(ManualKind.Heading, "Modelled instruments"),
            ManualBlock(ManualKind.Para, "Not recordings and not filtered noise - models of how the real thing works, so they behave like it under the hands."),
            ManualBlock(ManualKind.Bullet, "**Filament** - strings, plucked, bowed or blown at, with a body and sympathetic strings."),
            ManualBlock(ManualKind.Bullet, "**Brazen** - brass: lips blown open against a tube, from a trumpet to a tuba on one control."),
            ManualBlock(ManualKind.Bullet, "**Timber** - woodwinds: a reed or a jet of air, a tube, and the holes down the side of it."),
            ManualBlock(ManualKind.Bullet, "**Resonance** - eight struck objects that ring, and hear each other."),
            ManualBlock(ManualKind.Heading, "Drums"),
            ManualBlock(ManualKind.Bullet, "**Hexbeat** - drums by synthesis in the small-box vocabulary, grown to the kit those boxes never had."),
            ManualBlock(ManualKind.Bullet, "**Genesis** - the big box: a swept kick, circuit drift, and a bus the kick ducks."),
            ManualBlock(ManualKind.Bullet, "**Forage** - the sample drum machine. Thirteen pads, your own files, with a filter and an envelope on each."),
            ManualBlock(ManualKind.Bullet, "**Dice** - a loop cut into pieces and rolled, with a probability on every trigger."),
            ManualBlock(ManualKind.Heading, "Sound as material"),
            ManualBlock(ManualKind.Bullet, "**Pollen** - granular clouds that seed their own, from a file or from what is coming in live."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - multisamples: zones across the keyboard and velocity, SoundFonts, and a grain engine over the map."),
            ManualBlock(ManualKind.Bullet, "**Molt** - a voice you write for. Sing a take in and the piano roll tunes it."),
            ManualBlock(ManualKind.Bullet, "**Cipher** - a vocoder whose band map is the instrument."),
            ManualBlock(ManualKind.Heading, "Anything else"),
            ManualBlock(ManualKind.Bullet, "**Nexus** - a modular whose blocks are this app's own instruments and whose patch is text."),
            ManualBlock(ManualKind.Heading, "Audio"),
            ManualBlock(ManualKind.Bullet, "**Bias** - the four-track. Four lanes of recordings per cell, sounding together; record over the song and the take is cut at the scene lines. Its patches are **recording media** rather than sounds - a cassette, a Portastudio, a reel, a MiniDisc, a telephone - which colour what comes out and never the recordings."),
            ManualBlock(ManualKind.Heading, "Patches"),
            ManualBlock(ManualKind.Para, "Every machine ships with patches, shelved by family. **patch** at the top of the panel opens the browser; your own saved patches get a tab of their own and are the only ones you can delete."),
        ), listOf(
            ManualSection("Bias", "The four-track: recordings arranged along the song, four lanes at a time.", listOf(
                ManualBlock(ManualKind.Para, "Bias is the audio track. Where every other machine plays the notes in a cell, Bias plays the **recording** in a cell - four lanes of them, sounding together, so choosing between three takes is muting two and doubling a vocal is unmuting a second."),
                ManualBlock(ManualKind.Heading, "How it fits the song"),
                ManualBlock(ManualKind.Para, "There is no second timeline. A Bias cell is an ordinary clip, so a take sung across four scenes becomes **four cells naming the same file** at four offsets - nothing is copied, scenes of different lengths need nothing said about them, and it works identically in the arranger and in the clip launcher."),
                ManualBlock(ManualKind.Para, "A cell covers its bars **times the scene's repeat**, and plays straight through them: a scene played twice is one performance, not the same two seconds again."),
                ManualBlock(ManualKind.Heading, "Recording onto it"),
                ManualBlock(ManualKind.Para, "Tap the red dot beside a lane, arm the transport's record button, and press play. What you sing is written while the song plays under you and the other lanes keep playing - which is what overdubbing on a four-track is."),
                ManualBlock(ManualKind.Para, "**When you disarm, the take is cut at the scene lines.** One recording over a whole song becomes one cell per scene, and scenes the track had nothing in are made as they are reached. The whole recording stays in the sound library, so a split you did not want can be thrown away and the audio placed by hand."),
                ManualBlock(ManualKind.Para, "One lane records at a time, because there is one recorder. If the recorder fell behind and the take has a gap in it, it is **not** split - every moment after the gap would be in the wrong place - and it is left whole instead."),
                ManualBlock(ManualKind.Heading, "The editor"),
                ManualBlock(ManualKind.Para, "Opening a cell gives you the four lanes along the whole cycle:"),
                ManualBlock(ManualKind.Bullet, "drag a lane's **body** to move where it comes in;"),
                ManualBlock(ManualKind.Bullet, "drag either **end, top half**, to trim the recording without moving it;"),
                ManualBlock(ManualKind.Bullet, "drag either **end, bottom half**, to fade it in or out. The fades are equal-power, so **one lane fading out under another fading in is a crossfade** and holds a steady level between them;"),
                ManualBlock(ManualKind.Bullet, "tap the number at the left to **mute** the lane, and the dot below it to arm."),
                ManualBlock(ManualKind.Para, "A fade-out needs an end you can see, so on a take longer than its cell both halves of the right edge trim - which is the thing to do first anyway."),
                ManualBlock(ManualKind.Heading, "Level, mute and automation"),
                ManualBlock(ManualKind.Para, "The level and the mute on each lane are ordinary **machine parameters**, which is the whole reason they are there rather than on the recording: they automate in the strip under the grid, they map to a pad or a knob, and they record while you play. A muted section is a mute drawn in that cell."),
                ManualBlock(ManualKind.Heading, "Following the tempo"),
                ManualBlock(ManualKind.Para, "**tempo › takes** decides whether a take runs at the speed it was recorded at or follows the song. Following, it is read at the ratio between the two tempos **without its pitch moving**, so a take recorded at one tempo covers the same musical length at any other. Not following, it enters on the bar and runs at its own speed, and the cell says so in amber."),
                ManualBlock(ManualKind.Heading, "Playing a guitar through it"),
                ManualBlock(ManualKind.Para, "**monitor**, under **tempo**, mixes what is coming in into this track's own output - before its inserts, so an **amp** in slot one is in front of you while you play. Record with it up and the *recording is still dry*, because the recorder takes the input and not the track, so the amp can be changed afterwards exactly as the medium can."),
                ManualBlock(ManualKind.Para, "It is off by default, and on a phone's own speaker it will howl. Headphones, or an interface."),
                ManualBlock(ManualKind.Para, "**printed in**, beside it, is the other half of the choice. Those two slots are effects on the way *in*: what is on them is **recorded into the take**, because they run before the recorder sees the audio. An amp there is committed; an amp on the track's own **fx** is applied on playback and can be changed for ever afterwards. They are the same two slots the recording window shows, because they belong to the session rather than to this track."),
                ManualBlock(ManualKind.Heading, "Flattening"),
                ManualBlock(ManualKind.Para, "**comp** takes the four lanes, their levels, their mutes and their fades, and writes them into one file in lane 1. It does **not** flatten the medium - a patch here is a way of listening and a comp is an edit, so baking one into the other would make it permanent and apply it twice. The recordings it was made from stay in the library."),
                ManualBlock(ManualKind.Heading, "The patches are recording media"),
                ManualBlock(ManualKind.Para, "See **Patches** on the machines page: Bias's are a cassette, a Portastudio, a reel, a MiniDisc, a telephone, a wax cylinder. They colour what comes out and never the recordings, so trying one costs nothing and undoes itself. **Init** is the default and plays the file back untouched."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Record first, decide later.** Everything here - the medium, the tempo, the fades, even the split - is a decision you can change afterwards, because none of them touch the file."),
                ManualBlock(ManualKind.Para, "**A take may be half an hour.** Anything under two minutes is held in memory; past that it is converted once, in the background, and read from storage as it plays, so a vocal that runs the length of a song costs no more than a chorus does."),
            )),
            ManualSection("Brazen", "Brass by modelling: lips blown open against a tube.", listOf(
                ManualBlock(ManualKind.Para, "Brazen is a model of a brass instrument. A pair of lips, a length of tube, a bell at the end - and the note is what happens when the pressure behind the lips and the standing wave in the tube agree with each other."),
                ManualBlock(ManualKind.Heading, "Blowing it"),
                ManualBlock(ManualKind.Bullet, "**pressure** - how hard you blow, and the single most important control. Below a threshold nothing sounds; past it the note starts; past that again it gets brighter and eventually overblows. It is not a volume knob."),
                ManualBlock(ManualKind.Bullet, "**breath** - noise in the air stream."),
                ManualBlock(ManualKind.Bullet, "**bite** and **tension** - the lips: how tight and how damped. Tension against pressure is what decides which harmonic of the tube you land on, which is a real brass player's embouchure written as two numbers."),
                ManualBlock(ManualKind.Bullet, "**lipdamp** - the lip resonance's damping, with a floor under it. Without that floor the model can find a solution with no damping at all and screams."),
                ManualBlock(ManualKind.Heading, "The tube"),
                ManualBlock(ManualKind.Bullet, "**size** - how long, from a trumpet to a tuba."),
                ManualBlock(ManualKind.Bullet, "**bore** and **bell** - how the tube flares, which decides how much of the high end escapes rather than reflecting back."),
                ManualBlock(ManualKind.Bullet, "**loss** - how much is lost per round trip, stated per trip rather than per second so it means the same thing at every length."),
                ManualBlock(ManualKind.Bullet, "**brass** - the nonlinearity that makes brass brassy: at high pressure the wave steepens on its way down the tube, and that steepening is the blare."),
                ManualBlock(ManualKind.Heading, "A section"),
                ManualBlock(ManualKind.Para, "**lock** and **drift** turn one player into several who are nearly together: each copy drifts on its own and locks loosely to the others, which is what a section is. **growl** and **growlrate** are the flutter of a player growling into the mouthpiece."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**A tuba is blown hard.** Big instruments need *more* pressure, not less - the model behaves like the real thing, which surprises people."),
                ManualBlock(ManualKind.Para, "**Automate pressure across a note.** A swell is a pressure move, and it changes the timbre as it goes, which is the thing a volume fade cannot do."),
                ManualBlock(ManualKind.Para, "**Start from a patch and move `size` first** - the whole family is one control apart."),
            )),
            ManualSection("Cipher", "A vocoder whose band map is the instrument.", listOf(
                ManualBlock(ManualKind.Para, "Cipher is a vocoder: it analyses one sound in bands and imposes that shape on another. What makes this one different is that **the map between the analysis bands and the synthesis bands is a thing you can change**, and that map is where all the interesting sounds are."),
                ManualBlock(ManualKind.Heading, "The two sides"),
                ManualBlock(ManualKind.Para, "The **modulator** is what is analysed - usually a voice, from the live input. The **carrier** is what gets shaped, and Cipher has its own built in: an oscillator with **detune**, **pw**, **sub**, **noise** and **cardrive**, so you do not need a second track to play one."),
                ManualBlock(ManualKind.Heading, "The bank"),
                ManualBlock(ManualKind.Bullet, "**bands** - how many. Few is robotic and intelligible; many is smooth and less so."),
                ManualBlock(ManualKind.Bullet, "**low**, **high** and **slope** - where the bank sits and how it is spread across that range."),
                ManualBlock(ManualKind.Bullet, "**q** - how narrow each band is."),
                ManualBlock(ManualKind.Heading, "The map, which is the extra"),
                ManualBlock(ManualKind.Para, "Normally band 1 drives band 1. Here you can **remap** it: reverse the order so a bright sound comes out dark, spread it so the voice covers a wider range than it occupied, **freeze** it so the current shape is held while the carrier keeps playing, or **smear** it so neighbouring bands bleed into each other."),
                ManualBlock(ManualKind.Para, "**role** and the **dry**/**wet** pair decide which side is which and how much of each is heard, and **unvoiced** decides what happens to consonants - which a vocoder with no answer for turns into a lisp."),
                ManualBlock(ManualKind.Heading, "Following"),
                ManualBlock(ManualKind.Para, "**attack**, **release** and **smear** are the envelope followers on each band. Fast is articulate and can chatter; slow is smooth and can slur."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Consonants are the whole problem.** Turn `unvoiced` up until the words are intelligible, then back off until it stops hissing."),
                ManualBlock(ManualKind.Para, "**Freeze on a vowel is a pad.** Hold the map and play a chord underneath, and the vowel becomes an instrument."),
                ManualBlock(ManualKind.Para, "**Fewer bands than you think.** Sixteen articulate bands beat forty smooth ones for anything with words in it."),
            )),
            ManualSection("Cumulus", "Pads by spectrum: you describe the sound's shape and the machine builds it.", listOf(
                ManualBlock(ManualKind.Para, "Cumulus does not have oscillators in the usual sense. You describe a **spectrum** - which partials, how loud, how wide - and the machine builds a wavetable from it offline, then plays that back. It is the machine for pads, drones and anything that wants to be enormous."),
                ManualBlock(ManualKind.Heading, "Why it is built that way"),
                ManualBlock(ManualKind.Para, "Every partial is given a *bandwidth* rather than a single frequency: a smear of energy around where the harmonic would be. That smear is what makes the sound lush without any chorus, because each partial beats against its own spread rather than against a copy of itself."),
                ManualBlock(ManualKind.Para, "Building the table costs real work, so it happens **off the audio thread** when the spectrum settles. Everything from `morph` onwards is live and immediate; the spectrum controls are the ones with a moment's thought behind them."),
                ManualBlock(ManualKind.Heading, "The spectrum"),
                ManualBlock(ManualKind.Bullet, "**bandwidth** and **bwscale** - how wide each partial is, and whether the high ones are wider than the low ones. This is the main control and the one that makes it a pad."),
                ManualBlock(ManualKind.Bullet, "**tilt** - the overall slope from bass to treble."),
                ManualBlock(ManualKind.Bullet, "**stretch** - pushes the partials away from being whole-number multiples, which is what a piano's top octave and every bell have in common."),
                ManualBlock(ManualKind.Bullet, "**comb** and **period** - scallops the spectrum, taking out regular slices."),
                ManualBlock(ManualKind.Bullet, "**vowel** and its amount - bends the spectrum towards a formant."),
                ManualBlock(ManualKind.Bullet, "**odd** - the balance between odd and even partials: all-odd is a clarinet, all-even is hollow."),
                ManualBlock(ManualKind.Bullet, "**seed** - the random phases. Changing it gives a different sound with the same description."),
                ManualBlock(ManualKind.Heading, "Playing it"),
                ManualBlock(ManualKind.Para, "**detune**, **spread** and **width** stack copies; **drift**, **driftrate** and **scatter** keep the cloud moving. Then an ordinary filter with its own envelope, an amp envelope, and drive."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Long attacks and long releases.** This machine is at its best when notes overlap; short ones waste what makes it different."),
                ManualBlock(ManualKind.Para, "**Move `morph`, not the spectrum, while playing.** The spectrum rebuilds; morph is instant."),
                ManualBlock(ManualKind.Para, "**Stretch a little goes a long way** - a few per cent is a grand piano, a lot is a gong."),
            )),
            ManualSection("Dice", "A loop cut into pieces, and rolled.", listOf(
                ManualBlock(ManualKind.Para, "Dice takes one loop and cuts it into slices, then plays those slices back with a probability on every trigger. It is the machine for breaks, and for the thing a break does when it stops being a loop."),
                ManualBlock(ManualKind.Heading, "The cut"),
                ManualBlock(ManualKind.Para, "**slices** is how many pieces, and **cut** is where the cuts fall - from an even division to the loop's own transients. Each slice then has its own **level**, **pan**, **pitch**, **decay** and **dir**, so a slice can be quieter, lower or backwards without touching the others."),
                ManualBlock(ManualKind.Heading, "The dice"),
                ManualBlock(ManualKind.Para, "Five of them, each a probability rolled per trigger:"),
                ManualBlock(ManualKind.Bullet, "**swap** - play a different slice instead of this one."),
                ManualBlock(ManualKind.Bullet, "**reverse** - play it backwards."),
                ManualBlock(ManualKind.Bullet, "**stutter**, with **stutterdiv** - repeat a fraction of it."),
                ManualBlock(ManualKind.Bullet, "**drop** - play nothing."),
                ManualBlock(ManualKind.Bullet, "**jump**, with **jumprange** - move somewhere else in the loop and carry on from there."),
                ManualBlock(ManualKind.Para, "**seed** decides the rolls, and **hold** freezes them - so a roll you liked can be kept rather than lost to the next bar. That pairing is the whole machine: turn the dice up until something good happens, then hold it."),
                ManualBlock(ManualKind.Heading, "Playing it"),
                ManualBlock(ManualKind.Para, "The slices sit on the grid like drum voices, so a pattern of slice numbers is a re-ordering of the loop written out. **rate**, **gate**, **pitch**, **fine** and **accent** are the playback, and there is a filter and drive after."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Hold is the point.** Unheld, Dice is different every bar and tiring; held on a good roll, it is a part."),
                ManualBlock(ManualKind.Para, "**Cut on transients, not evenly, for a real break** - an even cut on a loop that swings puts every slice in slightly the wrong place."),
                ManualBlock(ManualKind.Para, "**A seed makes it repeatable**, so an exported song sounds like the one you arranged."),
            )),
            ManualSection("Filament", "Strings by modelling: plucked, bowed or blown at, and they hear each other.", listOf(
                ManualBlock(ManualKind.Para, "Filament is a physical model of a string. Not a recording of one and not a filtered noise burst - a delay line with a filtered loop, excited at a point, which is what a string *is*. Everything it can do follows from that."),
                ManualBlock(ManualKind.Heading, "The exciter"),
                ManualBlock(ManualKind.Para, "**exciter** chooses how the string is set going - plucked, struck, bowed, blown, or by **the live input**, which means you can excite a modelled string with a microphone."),
                ManualBlock(ManualKind.Bullet, "**position** - where along the string it is excited. The same node arithmetic as a struck object: exciting at a node silences that partial, so moving this changes the timbre far more than any filter."),
                ManualBlock(ManualKind.Bullet, "**hardness** - how sharp the excitation is."),
                ManualBlock(ManualKind.Bullet, "**grit** and **length** - how noisy and how long it is."),
                ManualBlock(ManualKind.Heading, "The string"),
                ManualBlock(ManualKind.Bullet, "**couple**, **detune** and **spread** - a course of two strings, slightly apart, which is what a twelve-string and a piano's middle octaves have in common."),
                ManualBlock(ManualKind.Bullet, "**damper** - a felt on the string, at a position, which is the una corda pedal and also every muted guitar part."),
                ManualBlock(ManualKind.Heading, "The body"),
                ManualBlock(ManualKind.Para, "Four modes standing in for a box, with **size** moving them together and **bodydamp** widening them - the difference between a guitar and a crate - and **bodymix** for how much of it you hear. There are sympathetic strings too, which ring when the played string excites them."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**The loop is solved from its own phase.** You do not need to know that, but it is why the tuning holds when you move `body` and `damper` - things that on a naive model would pull the pitch about."),
                ManualBlock(ManualKind.Para, "**A string cannot hold DC**, and this one does not, which is why long sustains stay steady instead of drifting into a thump."),
                ManualBlock(ManualKind.Para, "**Ringing is a time, not a gain.** If a note is too loud, turn it down; if it rings too long, shorten the decay. Turning the loop gain down to shorten it detunes the string."),
                ManualBlock(ManualKind.Para, "**Exciter position is the first control to reach for**, before the filter and before the body."),
            )),
            ManualSection("Forage", "The sample drum machine: thirteen pads, your own files, and a filter and envelope on each.", listOf(
                ManualBlock(ManualKind.Para, "Forage is where recordings become drums. Thirteen pads, each holding a file you imported or recorded, and each with enough processing to make it fit."),
                ManualBlock(ManualKind.Heading, "A pad"),
                ManualBlock(ManualKind.Bullet, "**level**, **pan**, **pitch** and **decay**."),
                ManualBlock(ManualKind.Bullet, "**start** and **end** - the part of the file that plays, which is how one long recording becomes several pads."),
                ManualBlock(ManualKind.Bullet, "**mode** - once, loop or hold."),
                ManualBlock(ManualKind.Bullet, "**dir** - forwards or reversed."),
                ManualBlock(ManualKind.Bullet, "**cutoff** with a filter type, and **crush** for bit reduction."),
                ManualBlock(ManualKind.Bullet, "**pdecay** - a pitch envelope, so a sample can fall the way a drum does."),
                ManualBlock(ManualKind.Bullet, "**choke** - which group this pad belongs to. Two pads in one choke group cut each other off, which is how an open hat stops when the closed one hits."),
                ManualBlock(ManualKind.Heading, "The slice source"),
                ManualBlock(ManualKind.Para, "There is a fourteenth slot above the pads: **one file for the whole machine**, which the pads take slices of. Load a bar of a break into it, ask for thirteen slices, and every pad is a piece of it - one decode and one copy in memory rather than thirteen."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Choke groups are not optional.** Hats without one sound like two hats; with one they sound like a hat."),
                ManualBlock(ManualKind.Para, "**Trim before you tune.** A sample with silence at the front plays late, and no amount of micro-timing fixes what a trim would have."),
                ManualBlock(ManualKind.Para, "**`start` is a performance control.** Automate it across a bar and a single hit becomes a stutter."),
                ManualBlock(ManualKind.Para, "**The sound library remembers what a song is using** - the delete page says \"a track is playing this\" before it lets you remove a file, which is the failure that set exists to prevent."),
            )),
            ManualSection("Formulate", "The 8-bit machine, and an equation you can type into it.", listOf(
                ManualBlock(ManualKind.Para, "Formulate is a chip synth: pulse, triangle and noise, the hardware that made game music, with the crunch left in. And then the extra - **a waveform is something you write**."),
                ManualBlock(ManualKind.Heading, "The hardware"),
                ManualBlock(ManualKind.Bullet, "**wave** chooses pulse, triangle, noise or the written formula."),
                ManualBlock(ManualKind.Bullet, "**duty** is the pulse width, with **pwmrate** and **pwmdepth** sweeping it - the sound of every chiptune lead ever made."),
                ManualBlock(ManualKind.Bullet, "**sub** adds an octave below, and **noiseshort** switches the noise between its long and short periods, which is the difference between a hiss and a metallic buzz."),
                ManualBlock(ManualKind.Bullet, "**bits**, **crush** and **smooth** are the converter: how many bits, how often it updates, and how much of the resulting staircase is filtered off. All the way down is a fault; part of the way down is the sound."),
                ManualBlock(ManualKind.Heading, "The tracker tables"),
                ManualBlock(ManualKind.Para, "Three of them - **arp**, **duty** and **vol** - written as text and stepped through per tick, the way a tracker instrument does it. An arpeggio table of `0 4 7` played fast is a chord from one voice, and that is how those records were made."),
                ManualBlock(ManualKind.Heading, "The formula"),
                ManualBlock(ManualKind.Para, "`formula` is an expression with **x** in scope, where x runs from 0 to 1 across one cycle of the waveform. `sin(x*2*pi)` is a sine. `x*2-1` is a saw. `(x<0.3)?1:-1` is a pulse with a 30% duty. Anything you can write, the oscillator plays."),
                ManualBlock(ManualKind.Para, "**formulamode** decides whether it is evaluated per cycle or per sample, and the three **macros** `a`, `b` and `c` are knobs you can refer to by name inside the expression - so a formula can have controls."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Write the formula against a macro, then automate the macro.** `sin(x*2*pi*a)` with `a` on a lane is a sweep no wavetable contains."),
                ManualBlock(ManualKind.Para, "**The tracker tables are where the personality is.** A flat patch with a good volume table sounds better than a clever formula with none."),
                ManualBlock(ManualKind.Para, "**A typed formula that fails says so** on the panel rather than going quiet, which is the one thing worse than a wrong note."),
            )),
            ManualSection("Genesis", "The big drum box: circuit drift, and a bus compressor with the kick wired to its side chain.", listOf(
                ManualBlock(ManualKind.Para, "Genesis is the other drum machine - the large one, after the boxes that defined house and techno. Twelve voices, more weight than Hexbeat, and two ideas that Hexbeat does not have."),
                ManualBlock(ManualKind.Heading, "The two ideas"),
                ManualBlock(ManualKind.Para, "**Circuit drift.** Real analogue drum machines are never quite the same twice: components warm up and every hit is a little different. **drift** is that, and a small amount of it is the difference between a machine and a loop."),
                ManualBlock(ManualKind.Para, "**A bus with the kick on its side chain.** The whole kit runs through a compressor - **comp**, **compattack**, **comprelease** - and **duck** wires the kick into it, so every kick pulls the rest of the kit down and lets it back. That pumping is not an effect added afterwards here; it is part of the instrument, which is how those records were made."),
                ManualBlock(ManualKind.Heading, "The kit"),
                ManualBlock(ManualKind.Bullet, "**kick** - tune, decay, level, **sweep**, **punch**, **click** and **drive**. The sweep is the long pitch fall that makes this kick this kick; the click is the attack transient; the drive is where it stops being polite."),
                ManualBlock(ManualKind.Bullet, "**snare**, **clap** with its spread and tone, **rim**."),
                ManualBlock(ManualKind.Bullet, "**toms**, **hats** with a shared tone and tune and separate open and closed decays."),
                ManualBlock(ManualKind.Bullet, "**crash** and **ride**, the ride with its own **bell**."),
                ManualBlock(ManualKind.Bullet, "**cowbell** - tune, decay, level, and yes."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Set the duck before you set the levels.** How much the kit moves under the kick changes how loud everything else needs to be, so doing it the other way round means doing it twice."),
                ManualBlock(ManualKind.Para, "**The kick's drive is a mix control.** It adds harmonics that a small speaker can reproduce, so a kick that disappears on a phone usually wants drive rather than level."),
                ManualBlock(ManualKind.Para, "**A little drift, not a lot.** Enough that two bars are not identical; not so much that the hats sound broken."),
            )),
            ManualSection("Hexbeat", "Drums by synthesis, in the small-box vocabulary, grown to the kit those boxes never had.", listOf(
                ManualBlock(ManualKind.Para, "Hexbeat makes its drums rather than playing recordings of them. Thirteen voices, each a small piece of synthesis aimed at one sound, in the vocabulary of the little silver drum machines - which means it is punchy, dry and slightly unreal, and it sits in a mix without being asked twice."),
                ManualBlock(ManualKind.Heading, "The kit"),
                ManualBlock(ManualKind.Para, "Kick, rim, snare, clap, three toms, closed and open hat, crash, ride, cowbell and clave. Those boxes had six or eight voices; this has the ones they left out, built in the same style."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Para, "Every voice has a **level** and at least a **tune** and a **decay**, and then whatever that particular sound is made of:"),
                ManualBlock(ManualKind.Bullet, "**kick** - tune, decay, punch. Punch is the pitch envelope: none is a tom, a lot is the swept kick."),
                ManualBlock(ManualKind.Bullet, "**snare** - tune, decay, tone and **snappy**, which is the balance between the drum and the noise across it."),
                ManualBlock(ManualKind.Bullet, "**hats** - one tone and tune shared, with separate closed and open decays, because on a real kit they are one instrument played two ways."),
                ManualBlock(ManualKind.Bullet, "**clap** - decay and tone, and the spread of the little burst of repeats that makes a clap a clap rather than a click."),
                ManualBlock(ManualKind.Bullet, "**cymbals** - decay and tone for crash and ride."),
                ManualBlock(ManualKind.Bullet, "**bell** and **clave** - tune and level."),
                ManualBlock(ManualKind.Para, "**accent** is how much a hard hit adds, and it applies across the kit."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**The grid is the editor for this machine.** It opens on the drum grid and stays there; a piano roll of thirteen one-tick notes answers no question the grid does not answer better."),
                ManualBlock(ManualKind.Para, "**Decay is the arrangement.** The same pattern with short decays is tight and with long ones is spacious - it is a faster edit than changing the notes."),
                ManualBlock(ManualKind.Para, "**Use the trig lane.** Probability on a hat and a ratchet on a snare turn a sixteen-step loop into something that does not repeat, and neither is a note you have to draw."),
                ManualBlock(ManualKind.Para, "**For the sampled equivalent, see Forage**; for the bigger, louder relative, see Genesis."),
            )),
            ManualSection("Manual", "The organ: two manuals and pedals over one shared generator, four models, and a cabinet that spins.", listOf(
                ManualBlock(ManualKind.Para, "Manual is a tonewheel organ. Two keyboards and a pedalboard share **one generator of ninety-one wheels**, which is the single fact that makes an organ sound like an organ: the same wheel serves the fifth of one note and the octave of another, so a chord is never quite in tune with itself and the beating between the notes is the instrument."),
                ManualBlock(ManualKind.Heading, "The drawbars"),
                ManualBlock(ManualKind.Para, "Nine per manual, and they are the patch. **tab16** through **tab1** - or, in the app's names, the combo section's tabs - each add one harmonic of the note at whatever level you pull them to. Everything an organ player knows is in those nine numbers."),
                ManualBlock(ManualKind.Heading, "The four models"),
                ManualBlock(ManualKind.Para, "**model** chooses what the generator is:"),
                ManualBlock(ManualKind.Bullet, "the **combo** - transistor, buzzy, with its own attack shape."),
                ManualBlock(ManualKind.Bullet, "the **tonewheel** - the big American console, with **leakage** (wheels bleeding into their neighbours), **hum** and **age**."),
                ManualBlock(ManualKind.Bullet, "the **reeds** - a reed organ, with **pressure**, **buzz** and a tremulant."),
                ManualBlock(ManualKind.Bullet, "the **pipes** - **principal**, **flute**, **string**, **reed** and **mixture** stops, with **chiff** on the attack and **tracker** noise."),
                ManualBlock(ManualKind.Heading, "The click, and why it matters"),
                ManualBlock(ManualKind.Para, "A real tonewheel organ's key contacts make and break one at a time, so a note starts with a burst of clicks. **click**, **clickoff** and **contacts** are that, and turning them off makes the machine sound instantly synthetic. It is the most recognisable thing about the instrument and it is not a tone control."),
                ManualBlock(ManualKind.Heading, "The cabinet"),
                ManualBlock(ManualKind.Para, "The rotary speaker is part of this machine rather than an effect after it: a horn over a counter-rotating drum, split at 800 Hz, each with its own rate and its own ramp up and down, Doppler as a modulated delay, and microphones at a distance and an angle. Its phase is also a **modulation source**, so anything in the matrix can be driven by where the horn is pointing."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Change the rotary speed, do not set it.** The sound of the instrument is the ramp between slow and fast, not either end."),
                ManualBlock(ManualKind.Para, "**Percussion and the drawbars fight on purpose.** That is how the originals were wired, and leaving it alone is usually right."),
            )),
            ManualSection("Molt", "A voice you write for: sing a take in, and the piano roll tunes it.", listOf(
                ManualBlock(ManualKind.Para, "Molt takes a sung recording and makes an instrument of it. Not a sampler - it finds the **glottal pulses** in the take, the individual openings of the vocal folds, and lays them down again at a new spacing. Moving the spacing moves the pitch; leaving the grain's own shape alone leaves the formants where they were, so the voice does not turn into a chipmunk."),
                ManualBlock(ManualKind.Heading, "The extra: the roll does the tuning"),
                ManualBlock(ManualKind.Para, "This is the machine's whole idea. **Draw the notes you want in the piano roll, sing anything, and the take is pulled onto those notes.** The melody comes from the clip and not from a knob."),
                ManualBlock(ManualKind.Bullet, "**tune** - how hard it is pulled. All the way is hard-tune, part of the way is a correction."),
                ManualBlock(ManualKind.Bullet, "**rate** - how quickly it gets there, which is the difference between a natural slide and the stepped sound."),
                ManualBlock(ManualKind.Bullet, "**robot** - flattens the pitch entirely onto the note."),
                ManualBlock(ManualKind.Heading, "The voice"),
                ManualBlock(ManualKind.Bullet, "**formant** - moves the formants independently of the pitch, which is the size of the singer rather than their note."),
                ManualBlock(ManualKind.Bullet, "**mega** - a megaphone."),
                ManualBlock(ManualKind.Bullet, "**start** and **loop** - which part of the take is used, and whether it repeats."),
                ManualBlock(ManualKind.Para, "Then an ordinary filter, an amp envelope and drive."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Take the rumble out first.** The recording page's low cut exists for this: a hand holding a phone puts more than half the take's energy below seventy hertz, the pitch marks snap to *that* instead of the voice, and the whole machine comes apart. It is done for you on the way in, but a bad recording is still a bad recording."),
                ManualBlock(ManualKind.Para, "**Consonants are copied, not stretched.** The analysis knows which parts have a pitch and which do not, so the sibilants stay sharp instead of being smeared onto a note - which is exactly what makes a cheap pitch shifter sound cheap."),
                ManualBlock(ManualKind.Para, "**Sing flat and let the roll fix it** is a legitimate way to work here, and much faster than singing it right."),
            )),
            ManualSection("Mosaic", "The multisample player: zones across the keyboard and across velocity, and a grain engine over the top.", listOf(
                ManualBlock(ManualKind.Para, "Mosaic plays maps of samples. Where Forage gives you thirteen pads, Mosaic gives you an instrument: a file assigned to a range of keys and a range of velocities, and as many of those as the instrument needs."),
                ManualBlock(ManualKind.Heading, "The map"),
                ManualBlock(ManualKind.Para, "A **zone** is a file, a key range, a velocity range, a root note and a tuning. Build one by hand from your own recordings, or load a **SoundFont** and get the whole map at once - the reader is the app's own, so nothing is converted outside and nothing is lost on the way in."),
                ManualBlock(ManualKind.Bullet, "**keyfade** and **velfade** - crossfades between neighbouring zones, so the seams stop being audible. Without them a multisample is a series of steps; with them it is an instrument."),
                ManualBlock(ManualKind.Bullet, "**scan** and **scanamt** - a **layer scan**: move continuously through the layers that would otherwise be chosen by velocity. It is how you play the quiet sample and the loud one as a blend rather than as a choice."),
                ManualBlock(ManualKind.Heading, "Playing a zone"),
                ManualBlock(ManualKind.Para, "**start**, **loop**, **reverse**, **envfrom** and **filemod** decide how the file itself is read, then there is a full synth after it: a filter with its own envelope and key tracking, two envelopes, two LFOs, glide and voice modes."),
                ManualBlock(ManualKind.Heading, "The grains"),
                ManualBlock(ManualKind.Para, "**grain** turns on a granular layer over the map - **gsize**, **gdensity**, **gpos**, **gspray**, **gpitch** and **grate**. The same file, but read as a cloud rather than as a sample, which is a different instrument on the same material and does not need a second machine."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Set the crossfades before you judge the map.** Most maps that sound wrong are maps with hard seams."),
                ManualBlock(ManualKind.Para, "**A root note that is wrong makes everything wrong.** It is the one field with no forgiving setting."),
                ManualBlock(ManualKind.Para, "**Scan is the control people do not find.** A two-layer map with the scan on a mod wheel is a dynamic instrument from two files."),
                ManualBlock(ManualKind.Para, "**Big maps are big.** Mosaic can hold a lot; the sound library's delete page will tell you what a song is using before you remove anything."),
            )),
            ManualSection("Nexus", "A modular whose blocks are this app's own instruments, and whose patch is text.", listOf(
                ManualBlock(ManualKind.Para, "Nexus is the machine for building a machine. Its blocks are not generic oscillators and filters - they are **the app's own instruments**, so a Reflux filter, a Trinity oscillator or a Resonance mode bank can be wired into a graph together."),
                ManualBlock(ManualKind.Heading, "The patch is text"),
                ManualBlock(ManualKind.Para, "A Nexus patch is written out rather than drawn: a list of blocks and a list of connections, in a form you can read, copy, send to somebody and keep in a comment. It opens on a screen of its own because a graph needs room."),
                ManualBlock(ManualKind.Para, "Knobs are parameters in the ordinary sense - so anything in a Nexus patch can be automated, mapped to a controller and recorded, exactly as any other machine's controls can."),
                ManualBlock(ManualKind.Heading, "The macros"),
                ManualBlock(ManualKind.Para, "Eight of them, **macro1** to **macro8**, plus **morph**. A patch decides what they reach; the panel always shows the same eight. That means a complicated graph can present three useful controls, and the patch author decides which three."),
                ManualBlock(ManualKind.Heading, "Blocks worth knowing"),
                ManualBlock(ManualKind.Para, "Alongside the instrument blocks there is an **audio input** block, which is how anything coming into the phone can be routed through a graph - and the only way, today, to put a live signal through a rack's insert effects."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Build small and name your macros.** A graph with thirty blocks and no macros is one nobody can play, including you next week."),
                ManualBlock(ManualKind.Para, "**Morph is the performance control.** Wire it to the two or three things that change the patch's character and leave everything else alone."),
                ManualBlock(ManualKind.Para, "**It is not a beginner's machine and it does not pretend to be.** Everything Nexus can do, one of the other nineteen does more directly - what it offers is the combinations none of them cover."),
            )),
            ManualSection("Pollen", "Granular clouds that seed their own, from a file or from what is coming in live.", listOf(
                ManualBlock(ManualKind.Para, "Pollen reads a buffer as a cloud of short grains rather than as a sample. It has two sources - a file you mount, or **the live input**, captured into a ring as you play - and one view over both."),
                ManualBlock(ManualKind.Heading, "The cloud"),
                ManualBlock(ManualKind.Bullet, "**size** and **sizespread** - how long a grain is, and how much they vary."),
                ManualBlock(ManualKind.Bullet, "**density** and **jitter** - how many per second, and how irregular."),
                ManualBlock(ManualKind.Bullet, "**window** and **skew** - the grain's envelope shape."),
                ManualBlock(ManualKind.Bullet, "**position**, **scan** and **spray** - where in the buffer grains are taken from, whether that point moves, and how far either side they scatter."),
                ManualBlock(ManualKind.Bullet, "**snap** - pulls grain starts onto the buffer's own transients, so a rhythmic source stays rhythmic instead of becoming a wash."),
                ManualBlock(ManualKind.Bullet, "**panspread** and **width**."),
                ManualBlock(ManualKind.Heading, "The live source"),
                ManualBlock(ManualKind.Para, "**source** switches to the input, **buffer** sets how much is kept, **freeze** decides whether the ring rolls or holds, and **capture** grabs what is in it. A live cloud is **not saved with the song and is silent on export**, which the panel says on screen rather than leaving you to find out."),
                ManualBlock(ManualKind.Heading, "The extra: pollination"),
                ManualBlock(ManualKind.Para, "**bloom** and **generations**. Grains seed further grains: each one can spawn another, at a related position and pitch, up to a depth you set. At low settings it thickens; at high settings one note becomes a texture that keeps unfolding. **drift** and **mutate** decide how far the children stray from their parents."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Density and size trade against each other.** Long grains at high density is a wall; short grains at high density is a texture. Pick one and adjust the other."),
                ManualBlock(ManualKind.Para, "**Use `snap` on anything with a beat in it.** It is the difference between granulating a drum loop and erasing one."),
                ManualBlock(ManualKind.Para, "**Scatter onto a scale.** The pitch scatter can be quantised to a key, so a cloud stays in the song rather than beside it."),
            )),
            ManualSection("Ratio", "Six-operator FM, with the algorithm itself on a knob.", listOf(
                ManualBlock(ManualKind.Para, "Ratio is the FM machine. Six operators, each a sine that can be a carrier or a modulator, and the arrangement of them - the algorithm - is what makes FM sound like FM."),
                ManualBlock(ManualKind.Heading, "The extra: the algorithm morphs"),
                ManualBlock(ManualKind.Para, "Classic FM gives you a numbered list of algorithms and you pick one. Ratio gives you **two** - `algoa` and `algob` - and a **morph** knob between them. Halfway between a stack and a pair of parallel carriers is an arrangement no algorithm list contains, and it is a knob you can automate."),
                ManualBlock(ManualKind.Para, "This is the machine's whole reason for existing. A pad that opens from two operators to six over eight bars is one lane, not a patch change."),
                ManualBlock(ManualKind.Heading, "The operators"),
                ManualBlock(ManualKind.Para, "Each of the six has:"),
                ManualBlock(ManualKind.Bullet, "**ratio**, its frequency as a multiple of the note - and **fixed**, which unpins it from the note so it stays where it is put. Fixed operators are how you get a formant that does not move as you play up the keyboard."),
                ManualBlock(ManualKind.Bullet, "**level**, which for a modulator is the index - how much FM it applies - and for a carrier is how loud it is."),
                ManualBlock(ManualKind.Bullet, "**fb**, feedback into itself, which is how a sine becomes a saw."),
                ManualBlock(ManualKind.Bullet, "its own **A D S R**, because in FM the envelope on a modulator is the timbre and not the volume."),
                ManualBlock(ManualKind.Bullet, "**key** tracking, **fine**, **pan** and **mode**."),
                ManualBlock(ManualKind.Heading, "Around them"),
                ManualBlock(ManualKind.Para, "A filter with its own envelope, three envelopes, two syncable LFOs, and a mod matrix in the same shape as Trinity's."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Ratios that are whole numbers are harmonic; ones that are not are metallic.** 1, 2 and 3 give you pitched sounds. 1.41 and 3.14 give you bells and clangs. The interesting patches usually have both."),
                ManualBlock(ManualKind.Para, "**Modulator envelopes should be shorter than carrier envelopes.** That is what makes an FM electric piano: a bright attack that decays into a soft body, which is one operator's decay set short."),
                ManualBlock(ManualKind.Para, "**Feedback on the last operator in a stack is the cheapest brightness there is** - reach for it before adding another operator."),
            )),
            ManualSection("Reflux", "The acid bass: one oscillator, one filter that screams, and a line you play rather than program.", listOf(
                ManualBlock(ManualKind.Para, "Reflux is the machine this app is named around. One oscillator, one filter, one envelope - and the whole of it is arranged so that a bassline is *performed* into the sequencer rather than assembled in it."),
                ManualBlock(ManualKind.Heading, "The idea"),
                ManualBlock(ManualKind.Para, "The famous silver box had no velocity and no legato. It had **accent** and **slide**, and every acid line ever written is those two switches used well. Reflux keeps both, and makes them things you already know how to do:"),
                ManualBlock(ManualKind.Bullet, "**Accent is velocity.** Play a note harder and it is accented - louder, brighter, and with a sharper envelope into the filter."),
                ManualBlock(ManualKind.Bullet, "**Slide is legato.** Overlap two notes and the second slides into the first's pitch instead of retriggering. Let go before the next and it plucks."),
                ManualBlock(ManualKind.Para, "So a line is played in on the keyboard, or drawn with overlaps in the roll, and it behaves the way the records do."),
                ManualBlock(ManualKind.Heading, "The controls"),
                ManualBlock(ManualKind.Bullet, "**osc** - the waveform, from saw through to square, and a sub an octave below. The saw is the classic; the square is the other half of the vocabulary."),
                ManualBlock(ManualKind.Bullet, "**filter** - cutoff and resonance, plus the envelope amount and its decay. This is the instrument: almost everything anybody plays on one of these is a cutoff sweep with resonance up."),
                ManualBlock(ManualKind.Bullet, "**env** - one decay-shaped envelope, and how much of it reaches the filter. Short decays give the plucked sound; long ones give the rubbery one."),
                ManualBlock(ManualKind.Bullet, "**accent** - how much an accented note adds, to both level and filter. At nothing, velocity does nothing and you have a machine with no dynamics."),
                ManualBlock(ManualKind.Bullet, "**glide** - how long a slide takes. Long glides over a fast line stop sounding like slides and start sounding like a portamento pad, which is occasionally what you want."),
                ManualBlock(ManualKind.Bullet, "**drive** - the output stage, which is where the scream comes from. It scales against the level the signal reaches rather than against full scale, so a quiet patch drives the same as a loud one."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Resonance and drive together are the sound.** Resonance alone thins the bass out; drive alone thickens it without the whistle. Most classic patches have both up and the cutoff moving."),
                ManualBlock(ManualKind.Para, "**Automate the cutoff rather than turning it.** The strip under the grid records a knob as you move it, so a sixteen-bar filter sweep is one pass of the recording rather than a line you have to draw."),
                ManualBlock(ManualKind.Para, "**Two Refluxes is the other classic trick** - one plucked and one slid, panned apart, playing the same clip with the second's cutoff a little different."),
                ManualBlock(ManualKind.Para, "*Reflux was called Subvert in earlier releases. Songs and patches saved then open as Reflux.*"),
            )),
            ManualSection("Resonance", "Eight struck objects that ring - and hear each other.", listOf(
                ManualBlock(ManualKind.Para, "Resonance is modal percussion. Each of its eight pads is an object described by its **modes** - the frequencies it rings at and how long each one lasts - and playing it is striking that object. Nothing is sampled and nothing is a filtered noise burst; the ringing is the instrument."),
                ManualBlock(ManualKind.Heading, "What a pad is"),
                ManualBlock(ManualKind.Bullet, "**modes** - how many partials the object has. Few is a woodblock, many is a bell."),
                ManualBlock(ManualKind.Bullet, "**shape** - membrane, bar, plate, tube, bowl or metal, which sets the *ratios* between the modes. A bar's partials are nothing like a drum head's, and that difference is most of what tells them apart."),
                ManualBlock(ManualKind.Bullet, "**inharm** - stretches those ratios away from where the shape put them."),
                ManualBlock(ManualKind.Bullet, "**decay** and **damp** - how long it rings, and whether the top goes first."),
                ManualBlock(ManualKind.Bullet, "**hard** - how hard the striker is, which is really how much high end goes in."),
                ManualBlock(ManualKind.Bullet, "**hit** - **where** you strike it. This is the control worth knowing: a mode has nodes, and striking at a node does not excite that mode at all. Moving `hit` silences and revives whole partials, which is why the same object struck in two places is two instruments."),
                ManualBlock(ManualKind.Bullet, "**bend** and **bendtime** - a pitch fall after the strike, which is what a tom is."),
                ManualBlock(ManualKind.Bullet, "**drive**, **pan**, **level** and **couple**."),
                ManualBlock(ManualKind.Heading, "The coupling"),
                ManualBlock(ManualKind.Para, "**coupling** is how much the pads ring into each other. Strike one and the others answer, quietly, at their own frequencies - which is what a rack of real objects in one room does, and what makes a kit built here sound like one place rather than eight."),
                ManualBlock(ManualKind.Para, "**humanise** varies the strike a little each time."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Start with `hit` and `shape`, not with tune.** They decide what the object *is*; tuning it comes after."),
                ManualBlock(ManualKind.Para, "**Coupling is loud.** A little is a room; a lot is feedback with a pitch."),
                ManualBlock(ManualKind.Para, "**Long decays plus the grid is a tuned percussion instrument** - write a melody on the pads and let them overlap."),
            )),
            ManualSection("Timber", "Woodwinds by modelling: a reed or a jet of air, a tube, and holes down the side of it.", listOf(
                ManualBlock(ManualKind.Para, "Timber is the woodwind counterpart to Brazen. Where brass is lips against a tube, a woodwind is either a **reed** beating against a mouthpiece or a **jet** of air across an edge - and then a tube with holes in it."),
                ManualBlock(ManualKind.Heading, "The family"),
                ManualBlock(ManualKind.Para, "**family** chooses reed (clarinet, saxophone), double reed (oboe, bassoon) or air jet (flute). They are genuinely different mechanisms, not three filter settings:"),
                ManualBlock(ManualKind.Bullet, "a reed's table is **a curve**, not a switch - it closes gradually as the pressure rises, and that curve is the difference between a clarinet and a saxophone."),
                ManualBlock(ManualKind.Bullet, "an air jet has **aim**, how the stream sits across the edge, which is what a flute player's embouchure controls."),
                ManualBlock(ManualKind.Heading, "The tube"),
                ManualBlock(ManualKind.Bullet, "**bore** - cylindrical or conical. A cylinder closed at one end produces only odd harmonics, which is why a clarinet sounds hollow and a saxophone does not, and it falls straight out of the model."),
                ManualBlock(ManualKind.Bullet, "**body** and **bell** - the shape of the end."),
                ManualBlock(ManualKind.Bullet, "**loss** - stated per round trip, so it means the same at any length."),
                ManualBlock(ManualKind.Bullet, "**fingering**, **below** and **answer** - the tone-hole lattice. The tube is modelled **below the note**: the holes are open past the first one, and where the wave turns round is what the note is."),
                ManualBlock(ManualKind.Bullet, "**fork** - the cross-fingerings, which on a real instrument give you the notes between and sound slightly different from the ones that are not."),
                ManualBlock(ManualKind.Heading, "Blowing it"),
                ManualBlock(ManualKind.Para, "**pressure** and **breath** as on Brazen, with **jet** and **aim** for the flute family, and **tongue** for articulation."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Pressure decides the register.** Overblow a clarinet and it jumps a twelfth, not an octave - because of the odd harmonics - and this model does that."),
                ManualBlock(ManualKind.Para, "**The breath noise is most of the realism.** A flute with none is a sine."),
                ManualBlock(ManualKind.Para, "**Tongue between notes, not before them.** Articulation is what stops a phrase sounding like one long note with pitch changes."),
            )),
            ManualSection("Trinity", "Three oscillators, wavetables, two filters and a mod matrix: the one that does everything.", listOf(
                ManualBlock(ManualKind.Para, "Trinity is the general-purpose polysynth - the machine to reach for when what you want is not a specific idea but a *sound*. Three oscillators into two filters, with a modulation matrix over the top."),
                ManualBlock(ManualKind.Heading, "The oscillators"),
                ManualBlock(ManualKind.Para, "Each of the three has a wavetable rather than a waveform: a table is a row of shapes and **pos** moves through it, so a sweep from a hollow pulse to a full saw is one knob and one automation lane."),
                ManualBlock(ManualKind.Bullet, "**density** stacks copies of the oscillator, **detune** spreads them apart and **drift** makes each copy wander slowly on its own. Density with a little drift is where a thin oscillator becomes a section."),
                ManualBlock(ManualKind.Bullet, "**hard** is oscillator sync, and **pw** the pulse width, both of them the classic destinations for an envelope."),
                ManualBlock(ManualKind.Bullet, "**fm21** and **fm32** are the two FM paths - two into one, three into two - so Trinity can do the metallic end without being an FM machine."),
                ManualBlock(ManualKind.Bullet, "**noise** with its **colour** sits beside them, which is what a snare tail or a breathy attack is made of."),
                ManualBlock(ManualKind.Heading, "The filters"),
                ManualBlock(ManualKind.Para, "Two of them, and **route** decides whether they are in series, in parallel, or split with **balance** between them. Each has its own type, drive and drive type, plus key tracking and an envelope amount. A low-pass into a band-pass in series is a formant; the same two in parallel is a comb."),
                ManualBlock(ManualKind.Heading, "Modulation"),
                ManualBlock(ManualKind.Para, "Two LFOs, each with a wave, a rate that can sync to the transport, a delay, a phase, key sync, one-shot and slew - and a **mod matrix** where any source reaches any destination, with a second source that scales the first."),
                ManualBlock(ManualKind.Heading, "Using it well"),
                ManualBlock(ManualKind.Para, "**Start from the oscillator, not the filter.** Trinity's character is in the table position and the density; a patch that only moves the cutoff could have been any synth."),
                ManualBlock(ManualKind.Para, "**Two sources in one matrix row is the trick most people miss.** Setting src to an envelope and src2 to the mod wheel gives you an envelope you can fade in with your thumb, which is one row rather than two."),
                ManualBlock(ManualKind.Para, "**It is the hungriest machine here.** If a song is running out of processor, Trinity with high density is usually where it went - and freezing that clip gives it all back."),
            )),
        )),
        ManualSection("Effects and mixing", "Two inserts a track, two sends, a master.", listOf(
            ManualBlock(ManualKind.Heading, "Inserts"),
            ManualBlock(ManualKind.Para, "Each track has two insert slots. **fx** in the editor's bottom bar swaps the panel under the grid for them."),
            ManualBlock(ManualKind.Para, "Sixteen effects: delay, reverb, equaliser, distortion, compressor, filter, bitcrusher, phaser, flanger, chorus, tremolo, width, pitch shifter, harmonizer, **amp** and **gate**. Each has the controls you expect **and one more that you do not** - the extra is marked in the accent colour, so the familiar set stays recognisable and the addition is never a surprise."),
            ManualBlock(ManualKind.Heading, "The gate"),
            ManualBlock(ManualKind.Para, "**Gate** shuts below a level and opens above it. The four you expect are **threshold**, **attack**, **hold** and **release**; **hyst** is how far *below* the threshold the signal has to fall before it is willing to shut, which is what stops a note sitting on the threshold from flapping it open and closed."),
            ManualBlock(ManualKind.Para, "Two are not on a pedal:"),
            ManualBlock(ManualKind.Bullet, "**key** filters the *detector*, not the sound. A gate in front of a loud amp is listening to a pickup that hears mains hum, a room and a hand as well as the string, and all of those are low. Slide `key` up and the gate opens for a pick rather than for a building, while the note it passes keeps its bottom end."),
            ManualBlock(ManualKind.Bullet, "**duck** is how far down \"closed\" is. All the way is a gate; twelve decibels is what drums want, where silence between hits is a hole and the room going quiet is a tightening."),
            ManualBlock(ManualKind.Para, "There is no wet/dry `mix`, on purpose: half a gate is the noise at half level."),
            ManualBlock(ManualKind.Para, "**Where to put it.** Before the amp it kills the hiss your pickups bring in; after the amp it kills the hiss the amp makes, which is usually far more. On an input slot in the record window it is printed into the take, so the take itself is quiet."),
            ManualBlock(ManualKind.Heading, "The amp"),
            ManualBlock(ManualKind.Para, "**Amp** is a guitar amplifier, and it is a chain rather than a distortion: a preamp that clips lopsidedly, a tone stack whose three controls fight each other, a power stage whose supply sags when you dig in, and a speaker in a box. The order is the point - the tone stack sits *between* the two nonlinear stages, so it shapes what the second one distorts."),
            ManualBlock(ManualKind.Bullet, "**drive** and **bias** - the preamp. Bias is the tube sense: at nothing the clipping is symmetrical, and turning it up makes the two halves of the wave behave differently, which is most of what \"old and woolly\" means."),
            ManualBlock(ManualKind.Bullet, "**bass**, **mid**, **treble** and **stack**. They interact the way a real passive stack does: **bass and treble up scoops the mid**, and turning either of them back fills it in again. `stack` - us, uk or modern - changes how hard they fight, and also what reaches the first stage and how tightly the two stages are coupled, which is far more of the difference between two amps than their tone controls are."),
            ManualBlock(ManualKind.Bullet, "**presence** and **master** - the power stage. Presence sits inside its feedback loop rather than after it, so it makes the output stage work harder rather than just adding treble."),
            ManualBlock(ManualKind.Bullet, "**sag** - the supply drooping under load and taking a fifth of a second to come back. It is what makes an amp feel alive under the hands, and it is the control most simulations bury."),
            ManualBlock(ManualKind.Bullet, "**cab** with **size**, **cone**, **mic**, **edge** and **room**. The cabinet is modelled rather than sampled, and **that is what makes `size` and `cone` continuous**: you can sit between a practice combo, a four-by-twelve and a bass eight-by-ten, between cabinets that do not exist. `mic` walks off axis, `edge` moves from the centre of the cone to its rim, and `room` steps back from it. Switch `cab` off if you have your own."),
            ManualBlock(ManualKind.Para, "To play a guitar through it, see [Bias](04-the-machines/bias.md): a Bias track with its **monitor** up puts what is coming in through the track's inserts, so the amp is in front of you while you play and the recording stays dry."),
            ManualBlock(ManualKind.Para, "A slot can be bypassed without being emptied, which is the difference between comparing and deleting."),
            ManualBlock(ManualKind.Heading, "On the way in, and on the way out"),
            ManualBlock(ManualKind.Para, "There are two more effect slots that do not belong to a track: **the two on the input**. They are at the top of the recording window's **record** page, under **printed into the recording**, and on Bias's panel under **printed in**."),
            ManualBlock(ManualKind.Para, "The difference between them and a track's inserts is the whole reason they exist:"),
            ManualBlock(ManualKind.Bullet, "an effect **on the input** runs before anything hears the audio - before the recorder, before the monitor, before any machine that reads the input - so **what it does is printed into the take**;"),
            ManualBlock(ManualKind.Bullet, "an effect **on the track** runs on playback, so it can be changed, bypassed or swapped afterwards and the recording is untouched."),
            ManualBlock(ManualKind.Para, "So: an amp you have decided on goes on the input and is committed to the file. An amp you want to keep thinking about goes on the track. Both at once means two amps, which is a legitimate thing to want and easy to do by accident."),
            ManualBlock(ManualKind.Para, "Unlike a send, an input effect keeps its **mix**, because it is in series with the signal rather than beside it."),
            ManualBlock(ManualKind.Heading, "The mixer"),
            ManualBlock(ManualKind.Para, "The mixer pill opens the strips: one per track and one master."),
            ManualBlock(ManualKind.Bullet, "**Fader and meter** per track, with mute and solo."),
            ManualBlock(ManualKind.Bullet, "**Two sends**, to two effects shared by the whole song. Sends are how several tracks sit in one room without each paying for its own."),
            ManualBlock(ManualKind.Bullet, "**Pan**, and a MIDI row for what this track sends out."),
            ManualBlock(ManualKind.Bullet, "**The master** carries the limiter, and the meter that tells you whether you are asking it for too much."),
            ManualBlock(ManualKind.Heading, "The two sends"),
            ManualBlock(ManualKind.Para, "They start as a reverb and a delay, which is what a send is usually for, but either can hold **any of the fourteen effects**. The two chips in the master strip say what is on them: tap one to switch it off and on, hold it to choose the effect and set it up. Every channel's two send sliders take their names from the same place, so a strip says what it is sending to."),
            ManualBlock(ManualKind.Para, "A send is fully wet, always. What comes back is the effect and nothing else, because the dry sound is already in the mix on its own channel - so there is no wet/dry control in a send, and that is the one thing its editor does not offer that an insert's does."),
            ManualBlock(ManualKind.Para, "Some things are worth more on a send than in a track's own slot: a pitch shifter fed a little from several tracks is a chorus of octaves nobody is playing, and a bitcrusher on a send is a second, ruined copy of the mix sitting behind it."),
            ManualBlock(ManualKind.Heading, "Tempo, and what else the song is"),
            ManualBlock(ManualKind.Para, "The tempo is in the song header, and tapping it opens everything the song is counted in."),
            ManualBlock(ManualKind.Bullet, "**beats a minute** - a number you can type, with a step either side. Under it is **tap**: tap four times in time and it takes the average of the gaps."),
            ManualBlock(ManualKind.Bullet, "**bar** - the time signature, from 4/4 through 7/8. A scene can be given its own; this is the one the rest of the song counts in."),
            ManualBlock(ManualKind.Bullet, "**swing** - how late the offbeats sit. Straight is straight; **triplet** is the shuffle everybody means; the far end is further than any record. **swing on** chooses whether it bends pairs of sixteenths or pairs of eighths - a groovebox feel or a jazz one."),
            ManualBlock(ManualKind.Bullet, "**key** - what key the song is in, and which scale. It shades the notes that are not in it in the piano roll, and fits a new track with a matching scale. It moves nothing already written and overrides no track that has chosen its own scale: it is a statement about the song rather than an instruction to it."),
            ManualBlock(ManualKind.Para, "The **click** and **link** pages are behind the same window."),
            ManualBlock(ManualKind.Para, "### What swing does, and what it does not"),
            ManualBlock(ManualKind.Para, "Swing bends time rather than delaying notes: each pair of subdivisions is mapped onto itself with its midpoint moved late. Two notes a tick apart stay a tick apart and stay in order, so a part played in loosely swings with everything else instead of scattering."),
            ManualBlock(ManualKind.Para, "A **track can disagree** with the song - the drums shuffling while the bass stays straight is most of what swing is for."),
            ManualBlock(ManualKind.Para, "**What you play in is stored straight.** Playing against a swung song means playing swung times, so those times are put back through the swing before they are written. The roll shows where you meant the notes, the song plays them where you played them, and turning the swing down afterwards leaves a straight part rather than a limping one."),
            ManualBlock(ManualKind.Para, "The **click stays straight**, because it is what you are playing against."),
        )),
        ManualSection("Modifiers", "What a note becomes on its way in.", listOf(
            ManualBlock(ManualKind.Para, "Every track has three, and they sit in the row just above the keyboard. **A tap says whether one is running; holding it open lets you choose.** They are the same gesture as every other slot in the app."),
            ManualBlock(ManualKind.Para, "A modifier sits between what you play and what gets written down. Play one key with the chord modifier running and three notes sound - and if you are recording, three notes are what the clip keeps. The same is true of anything arriving from a MIDI keyboard or a controller: it comes in the same door."),
            ManualBlock(ManualKind.Para, "**What is in the clip is what you hear.** A clip plays straight to its machine; the modifiers are not in that path at all. So the piano roll always shows what the song is playing, and a part can be edited note by note after the fact."),
            ManualBlock(ManualKind.Para, "**They do not change anything already recorded.** Turning the arpeggio off does not un-arpeggiate a part you played with it on - those notes are in the clip now. That is deliberate: what you played is what you have, and if you want it different, undo and play it again."),
            ManualBlock(ManualKind.Heading, "Scale"),
            ManualBlock(ManualKind.Para, "Thirty-three scales, each with a key. With one running, the keyboard collapses to only the notes the scale allows, so a phone's worth of width goes further and a wrong note is not available to play. A note that would be out of key is moved to the nearest one that is, before it is written down."),
            ManualBlock(ManualKind.Para, "The piano roll can show the scale three ways - every note, the scale's notes lit, or only the scale's notes - from the **scl** corner."),
            ManualBlock(ManualKind.Para, "The song's own key, behind the tempo button, sets what the roll shades on a track that has no scale of its own."),
            ManualBlock(ManualKind.Heading, "Chord"),
            ManualBlock(ManualKind.Para, "Plays a chord from every note you play. Either a fixed shape that follows your finger, or the chord the running scale builds on that degree, so the harmony stays in key as the line moves. **strum** spreads the notes in time instead of landing them together, and a recorded chord keeps that spread."),
            ManualBlock(ManualKind.Heading, "Arpeggio"),
            ManualBlock(ManualKind.Para, "Takes the notes you are holding and plays them one at a time: the order, the rate, how many octaves it climbs, how long each note lasts, and a chance that any given step is skipped."),
            ManualBlock(ManualKind.Para, "Recording with it running writes the arpeggio out as notes - one per step, where each one landed. A held chord becomes a line you can then edit, retime or rewrite a note of, which is the thing an arpeggio normally will not let you do."),
        )),
        ManualSection("MIDI and playing with others", "Keyboards, clock, MPE and Link.", listOf(
            ManualBlock(ManualKind.Para, "**MIDI…** in the file menu is where all of this lives, in the order somebody asks the questions: what is coming in, where it goes, and what goes out."),
            ManualBlock(ManualKind.Heading, "Playing the app from a keyboard"),
            ManualBlock(ManualKind.Para, "USB and Bluetooth keyboards are handled by the app itself. Arriving notes go either to whichever track is open - so changing track changes what you are playing - or to a track you pin, so it stays put whatever you are looking at."),
            ManualBlock(ManualKind.Para, "**Per-note expression** is understood where a machine can use it. A controller that bends one finger without bending the others will bend one note without bending the others, on the machines that have somewhere to put it, and the zone and bend range are set here. It is recorded as well as played: a note remembers its own bend, pressure and slide."),
            ManualBlock(ManualKind.Heading, "Mapping a controller"),
            ManualBlock(ManualKind.Para, "Long-press redo to enter mapping mode. Every control that can be mapped says so, and tapping one arms it: move a knob or press a key on your controller and the two are joined. Knobs, faders, mixer controls and transport buttons can all be mapped, to a CC **or** to a note."),
            ManualBlock(ManualKind.Para, "A mapped parameter records into the automation lane for free, because it moves down the same path your finger does. A mapped action - play, stop, fill - never records, because a button press is not a value."),
            ManualBlock(ManualKind.Heading, "Clock"),
            ManualBlock(ManualKind.Para, "The app can send MIDI clock to hardware, with start, stop and song position, and it can follow somebody else's. Following means the tempo control goes quiet: the tempo is theirs."),
            ManualBlock(ManualKind.Para, "What goes out is set per track: notes, or clock, or both."),
            ManualBlock(ManualKind.Heading, "Link"),
            ManualBlock(ManualKind.Para, "Link shares tempo and the position within the bar with any other Link app on the same network, in both directions. Switch it on and the peer count appears. It carries the beat and the bar, not the song position - so everybody agrees on where the downbeat is without anybody being in charge."),
        )),
        ManualSection("Recording and samples", "Getting audio in, and what to do with it.", listOf(
            ManualBlock(ManualKind.Heading, "The recording window"),
            ManualBlock(ManualKind.Para, "One window does all of it, and it opens wherever audio is wanted - a pad on the sample machine, a loop for the slicer, a buffer for the granular, a take to sing into the voice machine."),
            ManualBlock(ManualKind.Bullet, "**Record** - choose which input, watch the level, and capture. The **tuner** at the top names whatever is being played and says how far off it is; under it, **printed into the recording** holds two effects that go into the file as it records, which is how a guitar amp gets onto a take rather than over it. Effects on a *track* are the other thing, and can be changed at any time. The tuner listens to the input *before* those two effects, because you tune an instrument rather than a recording - a gate set to shut on a quietly plucked string would otherwise leave the tuner with nothing to hear. It shows the nearest note, the needle's distance to it in cents over fifty either way, and goes green within four. It names nothing at all unless it is sure, so a room or a hand across the strings reads as no note rather than as a wrong one."),
            ManualBlock(ManualKind.Bullet, "**Edit** - trim the ends, set the level, and take the rumble off the bottom with a low cut."),
            ManualBlock(ManualKind.Bullet, "**Library** - everything you have recorded or imported, to use again."),
            ManualBlock(ManualKind.Para, "What it hands back is a file, so the same recording can be used by more than one machine."),
            ManualBlock(ManualKind.Heading, "Importing"),
            ManualBlock(ManualKind.Para, "Bring in WAV, AIFF, FLAC and MP3. Whatever the format, it is decoded once on the way in and stored as a WAV, so nothing downstream has to know about formats and a song load is never a decode."),
            ManualBlock(ManualKind.Heading, "Recording onto a track"),
            ManualBlock(ManualKind.Para, "**Bias** is the four-track, and recording onto it is how a song gets a voice on it. Open a Bias cell, tap the red dot beside the lane you want, arm the transport's record button, and press play: what you sing is written while the song plays under you, and the other lanes keep playing, which is what overdubbing on a four-track is."),
            ManualBlock(ManualKind.Para, "**The take is cut at the scene lines when you disarm.** One recording sung over a whole song becomes one cell per scene, each a window into the same file - so nothing is copied, and every scene you crossed now holds the part of the take that belongs to it. Scenes the track had nothing in are made as they are reached."),
            ManualBlock(ManualKind.Para, "The whole recording stays in the sound library under its own name, so a split you did not want can be thrown away and the audio placed by hand instead."),
            ManualBlock(ManualKind.Para, "Everything you do to a take afterwards - trimming it, fading it, crossfading one lane into another, flattening four lanes into one, and whether it follows the song's tempo or runs at the speed it was sung at - is on [Bias](04-the-machines/bias.md), and none of it touches the file."),
            ManualBlock(ManualKind.Para, "**A take may be half an hour long.** Anything under two minutes is held in memory as it always was; past that it is converted once, in the background, and read from storage as it plays - so a vocal that runs the length of a song costs no more memory than a chorus does. You will not notice either happening, except that the first time a long recording is used there is a moment while it is converted."),
            ManualBlock(ManualKind.Para, "One lane records at a time, because there is one recorder. Arming a second lane lets the first one go."),
            ManualBlock(ManualKind.Para, "Two things it will tell you rather than guess at. If the recorder fell behind and the take has a gap in it, it is **not** split - every moment after the gap would be in the wrong place - and it is left in the library whole. And if the transport never played, nothing was recorded against a scene and it says so."),
            ManualBlock(ManualKind.Heading, "The machines that take audio"),
            ManualBlock(ManualKind.Bullet, "**Forage** - a pad each, with a filter, a crusher and a pitch envelope."),
            ManualBlock(ManualKind.Bullet, "**Mosaic** - a map of zones across the keyboard and across velocity, from your own files or a SoundFont."),
            ManualBlock(ManualKind.Bullet, "**Pollen** - grains over the file, or over what is coming in live."),
            ManualBlock(ManualKind.Bullet, "**Dice** - the loop cut into slices you can roll."),
            ManualBlock(ManualKind.Bullet, "**Molt** - a sung take, retuned by the piano roll."),
            ManualBlock(ManualKind.Bullet, "**Cipher** and **Filament** can both take the live input as their source."),
            ManualBlock(ManualKind.Bullet, "**Bias** - four lanes of recordings, along the length of the song. Unlike the rest of these, its material belongs to the cells rather than to the machine; see [The machines](04-the-machines.md)."),
        )),
        ManualSection("Exporting", "Getting the song out.", listOf(
            ManualBlock(ManualKind.Para, "**Export…** in the file menu renders the song faster than real time, through the same engine that plays it - so what you export is what you heard, including the tail after the last note."),
            ManualBlock(ManualKind.Heading, "Formats"),
            ManualBlock(ManualKind.Bullet, "**WAV** and **AIFF** - uncompressed, at 16 or 24 bits."),
            ManualBlock(ManualKind.Bullet, "**FLAC** - the same samples, smaller."),
            ManualBlock(ManualKind.Bullet, "**MP3** - at the bitrate you choose."),
            ManualBlock(ManualKind.Para, "The depth row becomes a rate row for the lossy formats, because a bitrate is what that question means there."),
            ManualBlock(ManualKind.Heading, "Stems"),
            ManualBlock(ManualKind.Para, "Export stems and every track is written as its own file, in one pass, with the mix left alone. That is a mixing session somewhere else, without re-recording anything."),
            ManualBlock(ManualKind.Heading, "Two renders of the same song match"),
            ManualBlock(ManualKind.Para, "Exporting the same song twice gives two identical files, because every machine is put back to where it started before the render begins. If you are comparing two exports and they differ, something in between changed."),
        )),
        ManualSection("Settings", "What follows you rather than the song.", listOf(
            ManualBlock(ManualKind.Para, "Nothing in this window is saved into a song. These are statements about you, your eyes and this particular phone, so opening somebody else's song never changes how your app behaves."),
            ManualBlock(ManualKind.Heading, "display"),
            ManualBlock(ManualKind.Bullet, "**theme** - dark, light, or whatever the phone is doing."),
            ManualBlock(ManualKind.Bullet, "**interface size** - makes everything larger, for a dense screen or for eyes that want it. Four steps; the app lays itself out again as you tap."),
            ManualBlock(ManualKind.Bullet, "**screen while playing** - whether the screen is allowed to sleep."),
            ManualBlock(ManualKind.Heading, "audio"),
            ManualBlock(ManualKind.Bullet, "**audio buffer** - tight, balanced or safe. Tight is the lowest latency the device will give and will crackle on a phone that cannot keep up; safe buys a phone that cannot the room to finish late. The line under it is live: frames, milliseconds and how many times it has dropped out."),
            ManualBlock(ManualKind.Bullet, "**machine voice limit** - how many notes a track may hold at once. The oldest goes first."),
            ManualBlock(ManualKind.Bullet, "**effect quality** - full is everything; lean trades reverb density and distortion oversampling for processor."),
            ManualBlock(ManualKind.Heading, "record"),
            ManualBlock(ManualKind.Para, "The depth recordings and exports are written at."),
            ManualBlock(ManualKind.Heading, "songs"),
            ManualBlock(ManualKind.Para, "What a new song starts as: tempo, signature, the machine on its first track, and whether its first track comes with a scale already set."),
        )),
    )
}
